input[aria-invalid="true"]:focus {
  box-shadow: 0 0 0 3px rgba(255, 107, 107, 0.2);
  border-color: #ff6b6b;
}

input[type="text"]:valid:not(:placeholder-shown),
input[type="email"]:valid:not(:placeholder-shown),
input[type="tel"]:valid:not(:placeholder-shown) {
  border-color: #51cf66;
  background-color: #24382a;
}

input[type="text"]:valid:not(:placeholder-shown):focus,
input[type="email"]:valid:not(:placeholder-shown):focus,
input[type="tel"]:valid:not(:placeholder-shown):focus {
  box-shadow: 0 0 0 3px rgba(81, 207, 102, 0.2);
  border-color: #51cf66;
}

.helper-text {
  font-size: 0.875rem;
  color: #9ca3af;
  margin-top: 0.25rem;
}

.error-message {
  font-size: 0.875rem;
  color: #ff6b6b;
  margin-top: 0.25rem;
  display: none;
}

.error-message:not(:empty) {
  display: block;
}

.submit-button {
  padding: 0.875rem 1.5rem;
  background-color: #5b9bd5;
  color: #ffffff;
  border: 2px solid #5b9bd5;
  border-radius: 4px;
  font-weight: 600;
  font-size: 1rem;
  cursor: pointer;
  transition: all 0.2s ease;
  margin-top: 0.5rem;
}

.submit-button:hover {
  background-color: #4a89c9;
  border-color: #4a89c9;
}

.submit-button:focus {
  outline: none;
  box-shadow: 0 0 0 3px rgba(91, 155, 213, 0.3);
}

.submit-button:active {
  background-color: #3a78ba;
