class ContactForm {
  constructor(formId) {
    this.form = document.getElementById(formId);
    this.fullNameInput = document.getElementById('fullName');
    this.emailInput = document.getElementById('email');
    this.phoneInput = document.getElementById('phone');
    this.successMessage = document.getElementById('successMessage');

    this.form.addEventListener('submit', (e) => this.handleSubmit(e));

    this.fullNameInput.addEventListener('blur', () => this.validateFullName());
    this.emailInput.addEventListener('blur', () => this.validateEmail());
    this.phoneInput.addEventListener('blur', () => this.validatePhone());

    this.fullNameInput.addEventListener('input', () => {
      if (this.fullNameInput.getAttribute('aria-invalid') === 'true') {
        this.validateFullName();
      }
    });

    this.emailInput.addEventListener('input', () => {
      if (this.emailInput.getAttribute('aria-invalid') === 'true') {
        this.validateEmail();
      }
    });

    this.phoneInput.addEventListener('input', () => {
      if (this.phoneInput.getAttribute('aria-invalid') === 'true') {
        this.validatePhone();
      }
    });
  }

  validateFullName() {
    const value = this.fullNameInput.value.trim();
    const errorEl = document.getElementById('fullName-error');

    if (value === '') {
      this.setInvalid(this.fullNameInput, errorEl, 'Error: Full name is required.');
      return false;
    }

    if (value.length < 2) {
      this.setInvalid(this.fullNameInput, errorEl, 'Error: Full name must be at least 2 characters.');
      return false;
    }

    this.setValid(this.fullNameInput, errorEl);
    return true;
  }

  validateEmail() {
    const value = this.emailInput.value.trim();
    const errorEl = document.getElementById('email-error');
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

    if (value === '') {
      this.setInvalid(this.emailInput, errorEl, 'Error: Email address is required.');
      return false;
    }

    if (!emailRegex.test(value)) {
      this.setInvalid(this.emailInput, errorEl, 'Error: Enter a valid email like name@example.com.');
      return false;
    }

    this.setValid(this.emailInput, errorEl);
    return true;
  }

  validatePhone() {
    const value = this.phoneInput.value.trim();
    const errorEl = document.getElementById('phone-error') || this.createPhoneErrorElement();

    // Phone is optional, so empty is valid
    if (value === '') {
      this.setValid(this.phoneInput, errorEl);
      return true;
    }

    // If provided, validate format: allow various formats
    const phoneRegex = /^[\d\s\-\+\(\)]{10,}$/;

    if (!phoneRegex.test(value)) {
      this.setInvalid(this.phoneInput, errorEl, 'Error: Enter a valid phone number like (555) 123-4567 or 555-123-4567.');
      return false;
    }

    this.setValid(this.phoneInput, errorEl);
    return true;
  }

  setInvalid(input, errorEl, message) {
    input.setAttribute('aria-invalid', 'true');
    errorEl.textContent = message;
    errorEl.style.display = 'block';
  }

  setValid(input, errorEl) {
    input.setAttribute('aria-invalid', 'false');
    errorEl.textContent = '';
    errorEl.style.display = 'none';
  }

  createPhoneErrorElement() {
    const errorEl = document.createElement('p');
    errorEl.id = 'phone-error';
    errorEl.className = 'error-message';
    errorEl.setAttribute('role', 'alert');
    this.phoneInput.parentElement.appendChild(errorEl);
    return errorEl;
  }

  handleSubmit(e) {
    e.preventDefault();

    // Validate all fields
    const isFullNameValid = this.validateFullName();
    const isEmailValid = this.validateEmail();
    const isPhoneValid = this.validatePhone();

    if (!isFullNameValid || !isEmailValid || !isPhoneValid) {
      // Focus on first invalid field
      if (!isFullNameValid) {
        this.fullNameInput.focus();
      } else if (!isEmailValid) {
        this.emailInput.focus();
      } else if (!isPhoneValid) {
        this.phoneInput.focus();
      }
      return;
    }

    // Show success message
    this.form.style.display = 'none';
    this.successMessage.hidden = false;
    this.successMessage.focus();

    // In a real application, you would send the data to a server here
    console.log('Form submitted with:', {
      fullName: this.fullNameInput.value,
      email: this.emailInput.value,
      phone: this.phoneInput.value
    });
  }
}

// Initialize form when DOM is ready
document.addEventListener('DOMContentLoaded', () => {
  new ContactForm('contactForm');
});

